import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.DYQ4mM3C.js";const k=JSON.parse('{"title":"Proxies","description":"","frontmatter":{},"headers":[],"relativePath":"proxies.md","filePath":"proxies.md","lastUpdated":1784264311000}'),n={name:"proxies.md"};function l(r,e,o,p,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="proxies" tabindex="-1">Proxies <a class="header-anchor" href="#proxies" aria-label="Permalink to &quot;Proxies&quot;">​</a></h1><p>Proxy mode is optional. Use it when an app or SDK accepts both a custom base URL and bearer token, and you want EnvVault to keep the real upstream credential out of the child process environment.</p><p>The default workflow does not need a proxy. A normal credential reference like <code>envvault://app/dev</code> resolves directly to the stored credential value.</p><p>Only proxy outputs use suffixes. <code>envvault://&lt;proxy&gt;/base-url</code> and <code>envvault://&lt;proxy&gt;/token</code> are generated by <code>envvault proxy add</code>; direct credential references never use <code>/value</code>.</p><h2 id="create-a-proxy" tabindex="-1">Create a Proxy <a class="header-anchor" href="#create-a-proxy" aria-label="Permalink to &quot;Create a Proxy&quot;">​</a></h2><p>Store the real credential:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">envvault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/dev</span></span></code></pre></div><p>The value is entered at a hidden terminal prompt. For non-interactive scripts, use <code>envvault credential set app/dev --value-stdin</code> and pipe the value over stdin.</p><p>Create a localhost proxy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">envvault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-proxy/dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --credential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app/dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allow-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /v1/messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --allow-method</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --project-binding</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span></span></code></pre></div><p>The command prints the references to paste into <code>.env</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENVVAULT_PROXY_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">envvault://api-proxy/dev/base-url</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENVVAULT_PROXY_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">envvault://api-proxy/dev/token</span></span></code></pre></div><p>Rename the left-hand environment variables to match the app or SDK:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">APP_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">envvault://api-proxy/dev/base-url</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">APP_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">envvault://api-proxy/dev/token</span></span></code></pre></div><p>The Admin UI shows the same snippet with a copy button after creating a proxy.</p><h2 id="policy-fields" tabindex="-1">Policy Fields <a class="header-anchor" href="#policy-fields" aria-label="Permalink to &quot;Policy Fields&quot;">​</a></h2><ul><li><code>credential</code>: The named OS credential store entry used by the proxy.</li><li><code>provider</code>: The proxy provider type. Supported values: <code>generic</code> and <code>openai-compatible</code>.</li><li><code>auth_mode</code>: The upstream authentication mode. Supported value: <code>bearer</code>.</li><li><code>target_url</code>: The fixed upstream API base URL the local proxy forwards to.</li><li><code>allowed_paths</code> and <code>allowed_methods</code>: The proxy allowlist enforced before the real upstream credential is added.</li><li><code>local_token_ttl</code>: The local proxy bearer token lifetime for a child process.</li><li><code>project binding</code>: The local approval tying proxy use to a path hash or git remote plus root.</li></ul><h2 id="secret-storage" tabindex="-1">Secret Storage <a class="header-anchor" href="#secret-storage" aria-label="Permalink to &quot;Secret Storage&quot;">​</a></h2><p>Credentials are stored in the OS credential store. Proxies point at named credential values. The config file stores non-secret policy and metadata only.</p><p>EnvVault does not write upstream credentials, database URLs, local proxy tokens, or Authorization header values into proxy config.</p><h2 id="project-binding" tabindex="-1">Project Binding <a class="header-anchor" href="#project-binding" aria-label="Permalink to &quot;Project Binding&quot;">​</a></h2><p>The default binding mode is <code>git-remote-and-root</code>. First use requires a TTY confirmation that records the approved project identity in user config. Non-interactive use fails closed when the binding is unknown.</p><p>Use <code>none</code> only for low-risk local workflows. Use <code>path-hash</code> when a project has no git remote but still needs local binding.</p><h2 id="use-a-proxy-in-the-docker-sandbox" tabindex="-1">Use a Proxy in the Docker Sandbox <a class="header-anchor" href="#use-a-proxy-in-the-docker-sandbox" aria-label="Permalink to &quot;Use a Proxy in the Docker Sandbox&quot;">​</a></h2><p>The same proxy references work with the experimental Docker runtime:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">envvault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node:22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.mjs</span></span></code></pre></div><p>For <code>envvault exec</code>, the generated base URL points at host loopback. For <code>sandbox run</code>, EnvVault rewrites it to an ephemeral host gateway address that the container can reach. In both cases, the application receives a temporary bearer capability and the upstream credential remains in the OS credential store and trusted proxy process.</p><p>Direct <code>envvault://&lt;credential&gt;</code> references are rejected in sandbox mode unless they exactly match a credential used by an attached outbound profile or <code>--allow-materialized-secrets</code> is explicit. The Docker prototype reports <code>brokered</code>: proxy method/path policy is enforced, but direct container egress is not blocked. See <a href="/envvault/sandbox.html">Experimental Docker Sandbox</a> for the exact boundary.</p><h3 id="preserve-the-provider-url" tabindex="-1">Preserve the provider URL <a class="header-anchor" href="#preserve-the-provider-url" aria-label="Permalink to &quot;Preserve the provider URL&quot;">​</a></h3><p>The same stored profile can be attached without using its generated base URL:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">APP_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">envvault://app/dev</span></span></code></pre></div><p>An application that already loads the mounted project <code>.env</code> can do so unchanged. Pass <code>--env-file .env</code> only when it expects the value in its process environment instead.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">envvault</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --agent-auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --outbound-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-proxy/dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> envvault-codex:local</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span></code></pre></div><p>EnvVault preserves the exact underlying credential reference in the container and supplies an authenticated <code>HTTP(S)_PROXY</code> plus an ephemeral public CA. A proxy-aware process can initialize its ordinary SDK from <code>APP_API_KEY</code> and call the original <code>target_url</code>. The host broker requires that reference in the configured bearer header, checks profile policy, and only then substitutes the real credential. Missing or mismatched references fail locally. The flag is repeatable. The first Docker adapter targets Node 22.21+ and does not force applications to use the proxy, so it remains <code>brokered</code> rather than <code>brokered-enforced</code>. The legacy profile format supports bearer late binding only.</p><p>For a trusted convenience session, <code>sandbox run --all</code> attaches every provider-proxy profile whose project binding permits the current workspace. It excludes other profile kinds and profiles bound elsewhere, but includes profiles configured with <code>project-binding none</code>. Do not combine it with an explicit <code>--outbound-profile</code>.</p><p>See <a href="/envvault/sandbox.html#original-url-outbound-profiles">Original-URL outbound profiles</a> and <a href="/envvault/rfcs/0003-url-preserving-outbound-broker.html">RFC 0003</a>.</p>`,36)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
